package com.hms.queue;
import com.hms.tenancy.*; import java.time.LocalDate; import java.util.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/hospitals/{tenantSlug}/queue-board") public class QueueBoardController {private final TenantRepository tenants;private final QueueTokenRepository tokens;public QueueBoardController(TenantRepository t,QueueTokenRepository q){tenants=t;tokens=q;} @GetMapping public QueueBoardDto board(@PathVariable String tenantSlug,@RequestParam LocalDate date){UUID tenant=tenants.findBySlug(tenantSlug).map(Tenant::getId).orElseThrow(()->new TenantNotFoundException(tenantSlug));List<QueueTokenDto> rows=tokens.findAllByTenantId(tenant).stream().filter(x->x.getTokenDate().equals(date)).sorted(Comparator.comparing(QueueToken::isPriority).reversed().thenComparing(QueueToken::getTokenNumber)).map(QueueTokenDto::from).toList();return new QueueBoardDto(date,rows);}}
